import React, { useEffect, useState } from "react";
import Card from "./Card";
import api from "../services/api";

const MonitoringWidget = () => {
  const [metrics, setMetrics] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    const fetchMetrics = async () => {
      try {
        const response = await api.get("/api/agent/metrics/"); // Correct API endpoint
        console.log("Fetched Metrics Data:", response.data); // Debugging output

        if (response.data.length > 0) {
          setMetrics(response.data);
          setLoading(false);
        } else {
          setError("No metrics available.");
          setLoading(false);
        }
      } catch (err) {
        console.error("Error fetching metrics:", err);
        setError("Failed to fetch metrics");
        setLoading(false);
      }
    };

    fetchMetrics();
  }, []); // Runs once when the component mounts

  if (loading) return <div>Loading...</div>;
  if (error) return <div>{error}</div>;

return (
    <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
      {metrics.map((metric, index) => (
        <div
          key={index}
          className="p-4 bg-white shadow-md rounded-lg border border-gray-200"
        >
          <h2 className="text-lg font-semibold text-gray-700">
            Server: {metric.server_id}
          </h2>
          <p className="text-sm text-gray-500">Timestamp: {new Date(metric.timestamp).toLocaleString()}</p>
          <hr className="my-2" />
          <p className="text-md font-medium text-blue-600">
            CPU Usage: {metric.cpu_usage}%
          </p>
          <p className="text-md font-medium text-green-600">
            Memory Usage: {metric.memory_usage}%
          </p>
          <p className="text-md font-medium text-red-600">
            Disk Usage: {metric.disk_usage}%
          </p>
          <p className="text-md font-medium text-purple-600">
            Uptime: {Math.floor(metric.uptime / 3600)} hours
          </p>
        </div>
      ))}
    </div>
  );
};

export default MonitoringWidget;
